/* 상감풍 스킨 글꼴(@font-face, data URI). tools/build-fonts.mjs 가 만든 파일 — 직접 고치지 말 것.
 * skin.js 앞뒤 어느 쪽에 불러도 된다: Zap.skins.intarsia.fontCss 에 들어간다. */
(function () {
  const g = /** @type {any} */ (globalThis);
  g.Zap = g.Zap || {};
  g.Zap.skins = g.Zap.skins || {};
  const css = "@font-face{font-family:\"IX Cinzel\";font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\")}@font-face{font-family:\"IX Cinzel\";font-style:normal;font-weight:900;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\")}@font-face{font-family:\"IX Cormorant\";font-style:normal;font-weight:500;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\")}@font-face{font-family:\"IX Cormorant\";font-style:normal;font-weight:700;font-display:swap;src:url(data:font/woff2;base64,) format(\"woff2\")}";
  if (g.Zap.skins.intarsia) g.Zap.skins.intarsia.fontCss = css;
  else g.Zap.skins.intarsia = { fontCss: css };
})();
